// ---- device helpers shared by the generated kernels ----
__device__ __forceinline__ float fx_gelu(float v) {
    return 0.5f * v * (1.0f + tanhf(0.7978845608f * (v + 0.044715f * v * v * v)));
}

__device__ __forceinline__ float fx_warp_max(float v) {
    #pragma unroll
    for (int o = 16; o > 0; o >>= 1) v = fmaxf(v, __shfl_down_sync(0xffffffffu, v, o));
    return v;
}

__device__ __forceinline__ float fx_warp_sum(float v) {
    #pragma unroll
    for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffffu, v, o);
    return v;
}

__device__ __forceinline__ float fx_block_max(float v, float* scratch) {
    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    const int warps = (blockDim.x + 31) >> 5;
    v = fx_warp_max(v);
    if (lane == 0) scratch[warp] = v;
    __syncthreads();
    if (warp == 0) {
        float t = (lane < warps) ? scratch[lane] : -INFINITY;
        t = fx_warp_max(t);
        if (lane == 0) scratch[0] = t;
    }
    __syncthreads();
    const float r = scratch[0];
    __syncthreads();   // keep scratch reusable by the next block reduction
    return r;
}

__device__ __forceinline__ float fx_block_sum(float v, float* scratch) {
    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    const int warps = (blockDim.x + 31) >> 5;
    v = fx_warp_sum(v);
    if (lane == 0) scratch[warp] = v;
    __syncthreads();
    if (warp == 0) {
        float t = (lane < warps) ? scratch[lane] : 0.0f;
        t = fx_warp_sum(t);
        if (lane == 0) scratch[0] = t;
    }
    __syncthreads();
    const float r = scratch[0];
    __syncthreads();   // keep scratch reusable by the next block reduction
    return r;
}

// kernel 0: attention_fused -- QK^T*scale -> softmax -> PV, one kernel
//   64 query rows x 256 head dim; 4 rows/block (1 warp each), 4 dimension chunks of 64
//   shared per stage: K 4224 halves (padded) overlaid with V 4096 floats, x2 stages
typedef union { __half h[4224]; float f[4096]; } fx_stage0_t;
__global__ void k_attention_fused_0(__half* __restrict__ T_att_attn_pv, const __half* __restrict__ P_Q, const __half* __restrict__ P_K, const __half* __restrict__ P_V) {
    __shared__ fx_stage0_t St[2];
    __shared__ __half Qs[4][256];
    __shared__ float  Pr[4][64];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int row = blockIdx.x * 4 + warp;
    const int j0 = lane;        // keys this lane scores: j0 and j1
    const int j1 = lane + 32;
    float acc[8];
    #pragma unroll
    for (int i = 0; i < 8; ++i) acc[i] = 0.0f;
    float invSum = 0.0f;

    if (row < 64) {   // stage this warp's query row once, reused by every chunk
        for (int dd = lane; dd < 256; dd += 32) Qs[warp][dd] = P_Q[row * 256 + dd];
    }

    // ------- phase 1: S = Q x K^T (register accumulation over dimension chunks) -------
    for (int i = threadIdx.x; i < 512; i += 128) {   // 8 halves per global transaction
        const int key = i / 8, off = (i - key * 8) * 8;
        const uint4 raw = *((const uint4*)(P_K + key * 256 + 0 + off));
        const __half* hv = (const __half*)&raw;
        #pragma unroll
        for (int t = 0; t < 8; ++t) St[0].h[key * 66 + off + t] = hv[t];
    }
    __syncthreads();
    float sc0 = 0.0f, sc1 = 0.0f;   // accumulate from zero: -INFINITY would poison the sum
    for (int c = 0; c < 4; ++c) {
        const int cur = c & 1, nxt = (c + 1) & 1;
        if (c + 1 < 4) {
            // issue the next K chunk before the FMAs below: Pascal has no cp.async, so the
            // global latency is hidden behind this chunk's arithmetic.
            for (int i = threadIdx.x; i < 512; i += 128) {   // 8 halves per global transaction
                const int key = i / 8, off = (i - key * 8) * 8;
                const uint4 raw = *((const uint4*)(P_K + key * 256 + (c + 1) * 64 + off));
                const __half* hv = (const __half*)&raw;
                #pragma unroll
                for (int t = 0; t < 8; ++t) St[nxt].h[key * 66 + off + t] = hv[t];
            }
        }
        if (row < 64) {
            #pragma unroll
            for (int dd = 0; dd < 64; ++dd) {
                const float qv = __half2float(Qs[warp][c * 64 + dd]);
                sc0 += qv * __half2float(St[cur].h[j0 * 66 + dd]);
                sc1 += qv * __half2float(St[cur].h[j1 * 66 + dd]);
            }
        }
        __syncthreads();
    }

    // ------- softmax: warp shfl_down max, exp, warp shfl_down sum -------
    if (row < 64) {
        sc0 *= 0.0625000000f;
        sc1 *= 0.0625000000f;
        float m = fx_warp_max(fmaxf(sc0, sc1));
        m = __shfl_sync(0xffffffffu, m, 0);
        const float p0 = expf(sc0 - m);
        const float p1 = expf(sc1 - m);
        Pr[warp][j0] = p0;
        Pr[warp][j1] = p1;
        float s = fx_warp_sum(p0 + p1);
        s = __shfl_sync(0xffffffffu, s, 0);
        invSum = 1.0f / s;
        __syncwarp();   // P is consumed by all lanes of this warp in phase 2
    }

    // ------- phase 2: O = P x V (same pipeline, the stage buffer now carries V as FP32) -------
    __syncthreads();
    for (int i = threadIdx.x; i < 512; i += 128) {   // 8 halves per global transaction
        const int key = i / 8, off = (i - key * 8) * 8;
        const uint4 raw = *((const uint4*)(P_V + key * 256 + 0 + off));
        const __half* hv = (const __half*)&raw;
        #pragma unroll
        for (int t = 0; t < 8; ++t) St[0].f[key * 64 + off + t] = __half2float(hv[t]);
    }
    __syncthreads();
    for (int c = 0; c < 4; ++c) {
        const int cur = c & 1, nxt = (c + 1) & 1;
        if (c + 1 < 4) {
            for (int i = threadIdx.x; i < 512; i += 128) {   // 8 halves per global transaction
                const int key = i / 8, off = (i - key * 8) * 8;
                const uint4 raw = *((const uint4*)(P_V + key * 256 + (c + 1) * 64 + off));
                const __half* hv = (const __half*)&raw;
                #pragma unroll
                for (int t = 0; t < 8; ++t) St[nxt].f[key * 64 + off + t] = __half2float(hv[t]);
            }
        }
        if (row < 64) {
            for (int j = 0; j < 64; ++j) {
                const float p = Pr[warp][j];
                acc[2 * c]     = fmaf(p, St[cur].f[j * 64 + lane], acc[2 * c]);
                acc[2 * c + 1] = fmaf(p, St[cur].f[j * 64 + lane + 32], acc[2 * c + 1]);
            }
        }
        __syncthreads();
    }

    // ------- store O, normalised by the softmax denominator -------
    if (row < 64) {
        #pragma unroll
        for (int c = 0; c < 4; ++c) {
            T_att_attn_pv[row * 256 + c * 64 + lane] = __float2half(acc[2 * c] * invSum);
            T_att_attn_pv[row * 256 + c * 64 + lane + 32] = __float2half(acc[2 * c + 1] * invSum);
        }
    }
}

// kernel 1: gemm_epilogue
//   out.mlp_act = out.mlp_fc1 -> bias_add+gelu  (64x1024 = 64x256 x (256x1024))
//   tile 64x64, depth step 32, 256 threads, 4x4 per thread
__global__ void k_gemm_epilogue_1(__half* __restrict__ T_out_mlp_act, const __half* __restrict__ T_res_add, const __half* __restrict__ P_W1, const float* __restrict__ P_b1) {
    __shared__ __half smA[64][32];
    __shared__ __half smB[32][64];
    const int tx = threadIdx.x % 16;   // 16 column groups of 4
    const int ty = threadIdx.x / 16;    // 16 row groups of 4
    const int rowBase = blockIdx.y * 64;
    const int colBase = blockIdx.x * 64;
    float acc[4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) acc[i][j] = 0.0f;
    }

    #pragma unroll
    for (int k0 = 0; k0 < 256; k0 += 32) {
        // cooperative tile load. Pascal has no cp.async, so global->shared is a plain
        // load/store pair guarded by __syncthreads() instead of an async copy.
        #pragma unroll
        for (int t = 0; t < 8; ++t) {   // A tile: 2048 elements
            const int idx = threadIdx.x + t * 256;
            const int ar = idx / 32;
            const int ac = idx - ar * 32;
            smA[ar][ac] = T_res_add[(rowBase + ar) * 256 + (k0 + ac)];
        }
        #pragma unroll
        for (int t = 0; t < 8; ++t) {   // B tile: 2048 elements
            const int idx = threadIdx.x + t * 256;
            const int bmRow = idx / 64;                  // k index inside the tile
            const int bmCol = idx - bmRow * 64;          // n index inside the tile
            smB[bmRow][bmCol] = P_W1[(k0 + bmRow) * 1024 + (colBase + bmCol)];
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < 32; ++kk) {
            float av[4], bv[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) av[i] = __half2float(smA[ty * 4 + i][kk]);
            #pragma unroll
            for (int j = 0; j < 4; ++j) bv[j] = __half2float(smB[kk][tx * 4 + j]);
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) acc[i][j] += av[i] * bv[j];
            }
        }
        __syncthreads();
    }

    // epilogue: bias_add gelu
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            const int row = rowBase + ty * 4 + i;
            const int col = colBase + tx * 4 + j;
            T_out_mlp_act[row * 1024 + col] = __float2half(fx_gelu((acc[i][j] + P_b1[col % 1024])));
        }
    }
}

// kernel 2: gemm_epilogue
//   out.mlp_b2 = out.mlp_fc2 -> bias_add  (64x256 = 64x1024 x (1024x256))
//   tile 64x64, depth step 32, 256 threads, 4x4 per thread
__global__ void k_gemm_epilogue_2(__half* __restrict__ T_out_mlp_b2, const __half* __restrict__ T_out_mlp_act, const __half* __restrict__ P_W2, const float* __restrict__ P_b2) {
    __shared__ __half smA[64][32];
    __shared__ __half smB[32][64];
    const int tx = threadIdx.x % 16;   // 16 column groups of 4
    const int ty = threadIdx.x / 16;    // 16 row groups of 4
    const int rowBase = blockIdx.y * 64;
    const int colBase = blockIdx.x * 64;
    float acc[4][4];
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) acc[i][j] = 0.0f;
    }

    #pragma unroll
    for (int k0 = 0; k0 < 1024; k0 += 32) {
        // cooperative tile load. Pascal has no cp.async, so global->shared is a plain
        // load/store pair guarded by __syncthreads() instead of an async copy.
        #pragma unroll
        for (int t = 0; t < 8; ++t) {   // A tile: 2048 elements
            const int idx = threadIdx.x + t * 256;
            const int ar = idx / 32;
            const int ac = idx - ar * 32;
            smA[ar][ac] = T_out_mlp_act[(rowBase + ar) * 1024 + (k0 + ac)];
        }
        #pragma unroll
        for (int t = 0; t < 8; ++t) {   // B tile: 2048 elements
            const int idx = threadIdx.x + t * 256;
            const int bmRow = idx / 64;                  // k index inside the tile
            const int bmCol = idx - bmRow * 64;          // n index inside the tile
            smB[bmRow][bmCol] = P_W2[(k0 + bmRow) * 256 + (colBase + bmCol)];
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < 32; ++kk) {
            float av[4], bv[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) av[i] = __half2float(smA[ty * 4 + i][kk]);
            #pragma unroll
            for (int j = 0; j < 4; ++j) bv[j] = __half2float(smB[kk][tx * 4 + j]);
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) acc[i][j] += av[i] * bv[j];
            }
        }
        __syncthreads();
    }

    // epilogue: bias_add
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            const int row = rowBase + ty * 4 + i;
            const int col = colBase + tx * 4 + j;
            T_out_mlp_b2[row * 256 + col] = __float2half((acc[i][j] + P_b2[col % 256]));
        }
    }
}

// kernel 3: layernorm over 64 rows x 256 columns, 256 threads/block
__global__ void k_norm_layernorm(__half* __restrict__ T_norm_layernorm, const __half* __restrict__ P_x, const float* __restrict__ P_gain, const float* __restrict__ P_beta) {
    __shared__ float scratch[8];
    const int row = blockIdx.x;
    float s = 0.0f, ss = 0.0f;
    for (int j = threadIdx.x; j < 256; j += 256) {
        const float v = __half2float(P_x[(long)row * 256 + j]);
        s += v; ss += v * v;
    }
    s = fx_block_sum(s, scratch);
    ss = fx_block_sum(ss, scratch);
    const float mean = s / 256.0f;
    const float var = ss / 256.0f - mean * mean;
    const float rstd = rsqrtf(var + 0.000010000f);
    for (int j = threadIdx.x; j < 256; j += 256) {
        const float v = (__half2float(P_x[(long)row * 256 + j]) - mean) * rstd * P_gain[j] + P_beta[j];
        T_norm_layernorm[(long)row * 256 + j] = __float2half(v);
    }
}

// kernel 4: single (1 elementwise op(s), 16384 elements)
__global__ void k_res_add(__half* __restrict__ T_res_add, const __half* __restrict__ T_norm_layernorm, const __half* __restrict__ T_att_attn_pv) {
    const long i = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= 16384L) return;
    T_res_add[i] = __float2half((__half2float(T_norm_layernorm[i]) + __half2float(T_att_attn_pv[i])));
}

